from 写入第二遍 import add
add('18_002',1.5,'16:9，青的半脸近景在画面右侧，保持原格圆眼、短小张口和汗的重点；扩展出的左半是她正在看的对手方向负空间，不增加实际挡脸的墙。固定机位。','青刚扬起的笑角突然停住，眼睛睁圆、瞳孔缩成一点，嘴唇松开一条短缝；她的头向后缩了半寸，肩头却僵在原处，额侧汗珠继续滑下，视线仍停在武士不断扩大的轮廓上。','浅冷灰白的图形底场，靠对手方向压进一层淡灰，不添加实体雾。','人物维持空地的冷白柔光，脸上的惊愕不靠骤改彩色照明。','一声细短吸气，膨胀低响在画外压近，环境声短暂被盖住。',phase='reaction',node={'青.阶段':'目击变身惊愕'},pcard={'opening':'青的挑战笑意尚未收完。','beats':['笑角停住、圆眼缩瞳','头缩而肩僵，继续看着武士'],'coupling':'变化规模打断她的挑衅节奏。','landing':'惊愕未消，仍未见完整形态。'},background_mode='graphic')
add('18_003',1,'16:9，贴近地面的巨大肢体接触特写，圆钝端部从画面左上压向右下石面；固定机位，保留压下与贴地关系。','巨大圆钝肢体继续下沉，末端碰到石面后短促压扁，体块沿长度方向回荡一下；贴地白色挤压纹朝外一抖，砂粒从接触边缘挤开，重量最终压住地面。','灰绿不规则石铺地与深灰缝隙，圆钝端部周围少量米灰细尘；不显示漫画技名排字。','上方冷白天空柔光，接触面下的暗部骤然加深后稳定。','厚重落地闷响，砂粒从接触缝挤出发出短促沙响，画外衣料扯裂余音。',phase='contact',node={'武士.形态':'巨大肢体先落地、完整形态未揭晓'},meaning='保留新形态局部承重先于全貌的揭晓顺序；技名是页面文字，不擅自添加旁白。')
add('18_004',3,'16:9，正面低位中全景；起幅含两侧粗壮撑地肢体与中间撑地的手，镜头缓慢上摇，经过肌肉胸腹与破衣，落在整个蹲伏形态和低垂头部同框的全貌。','武士巨大的身体从最后一团残尘里显出，两侧粗壮肢体已经压住石地，中间的手再握紧撑牢；宽阔肩背下沉一次，把刚才落地的震颤吞住，破黑外衣从两侧垂下。他的头低垂在胸前，先保持不动，随后从颈肩深处缓慢抬起一点，庞大身体已完全稳定。','灰绿石铺地在起幅占大部，上摇后退到下方；后面为铅蓝天空和低矮米灰残尘。','烟囱后侧开阔天空冷白柔光勾出躯体上缘，空地前方中性补光保持肌理与手部可见。','低沉承重余震、细石滚动、黑外衣末端落地的轻擦；呼吸变得低而厚。',phase='result',node={'武士.形态':'巨大半实力蹲伏形态已完整揭晓','武士.阶段':'撑地稳定'},meaning='原作正面蹲伏全貌、两侧支撑与中间撑地手保留；形态及比例以漫画本格为准，不加未画变形能力。')
